(()=>{const dialog=document.getElementById('place-dialog'),trigger=document.querySelector('.map-place-trigger');const photos=[{src:'/exploration/hoan-kiem.jpg',alt:'Tháp Rùa giữa hồ Hoàn Kiếm, Hà Nội',caption:'Tháp Rùa · Hồ Hoàn Kiếm',source:'https://commons.wikimedia.org/wiki/File:Thap_Rua.jpg'},{src:'/exploration/hanoi.jpg',alt:'Đường chân trời Hà Nội và núi Ba Vì',caption:'Hà Nội · Đường chân trời và núi Ba Vì',source:'https://commons.wikimedia.org/wiki/File:Hanoi_skyline_with_Ba_Vi_Mountain.jpg'}];let index=0;function show(i){index=(i+photos.length)%photos.length;const p=photos[index],img=document.getElementById('place-photo');img.src=p.src;img.alt=p.alt;document.getElementById('place-photo-caption').textContent=p.caption;document.getElementById('place-count').textContent=String(index+1).padStart(2,'0')+' / 02';document.getElementById('place-photo-source').href=p.source;}function open(){show(0);dialog.showModal();document.body.classList.add('place-open');}trigger.addEventListener('click',open);trigger.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open();}});document.querySelector('.place-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right)dialog.close();}});dialog.addEventListener('close',()=>{document.body.classList.remove('place-open');trigger.focus();});document.getElementById('place-prev').addEventListener('click',()=>show(index-1));document.getElementById('place-next').addEventListener('click',()=>show(index+1));dialog.addEventListener('keydown',e=>{if(e.key==='ArrowLeft')show(index-1);if(e.key==='ArrowRight')show(index+1);});})();